import{f as i}from"./catalog-Cnu0BOfU.js";import{F as s,b as r}from"./ExamKit-CfSTq4Nd.js";import{l as n}from"./index-B4wA5hSf.js";import{f as o}from"./recommend-pisvYrTP.js";const c=[{id:"not",word:"NOT",meaning:"The question asks you to find the one option that is false or does not belong. Three options are correct statements; the answer is the odd one out.",whyMisread:"Under time pressure the brain skips small negative words and starts looking for a true statement. The first familiar, correct-looking option then gets picked.",appears:"Which of these is one of the seven wastes?",actually:"Which of these is NOT one of the seven wastes — the one that does not belong?",example:{id:"trap-not-ex",topic:"1.4.4",category:"wording",difficulty:"trap",numerical:!1,traps:["not"],stem:"A Green Belt is running a waste walk in a service desk using the seven elements of waste from the syllabus. Which of the following is NOT one of those seven elements of waste?",options:["Correction","Conveyance","Non-utilized talent","Waiting"],answer:2,explanation:"The syllabus seven are Overproduction, Correction, Inventory, Motion, Overprocessing, Conveyance and Waiting. Non-utilized talent is the eighth waste added in the modern DOWNTIME framework, so it is NOT one of the syllabus seven.",whyWrong:["Correction IS one of the seven (fixing errors, rework, scrap). It is tempting because the eight-waste list calls it “Defects”, so the name looks unfamiliar.","Conveyance IS one of the seven — unnecessary movement of material or information (called Transportation in DOWNTIME).","","Waiting IS one of the seven — idle time for people or work."]},tempting:0,correctInterpretation:"Read the stem as “three of these are seven-waste names; find the impostor”. Check each option against the syllabus list and pick the one that fails.",strategy:"Circle or say the negative word aloud. Mark each option True/False against the stem, then choose the single False. If you find yourself agreeing with the option you picked, re-read the stem.",practice:{id:"trap-not-pr",topic:"1.2.5",category:"wording",difficulty:"trap",numerical:!1,traps:["not"],stem:"Which statement about defects and defective units is NOT correct?",options:["A single unit can contain more than one defect.","A defective unit contains at least one defect.","The number of defects can never be greater than the number of units inspected.","A defect is a failure to meet a customer requirement or specification."],answer:2,explanation:"Because one unit can carry several defects, total defects can exceed the number of units (DPU above 1.0 is possible). That statement is therefore the incorrect one.",whyWrong:["This is correct — for example, an invoice can have a wrong tariff and a wrong address.","This is correct — that is the definition of a defective.","","This is correct — it is the standard definition of a defect."]},highlight:["NOT"]},{id:"except",word:"EXCEPT",meaning:"“All of the following … EXCEPT” means three options fit the description and one does not. The answer is the exception.",whyMisread:"The stem starts with “All of the following are…”, which primes you to look for a matching item. Many candidates choose the first option that matches.",appears:"Which of these is an element of a project charter?",actually:"Which one of these is NOT normally an element of a project charter?",example:{id:"trap-except-ex",topic:"1.3.1",category:"wording",difficulty:"trap",numerical:!1,traps:["except"],stem:"All of the following are typically included in a Define-phase project charter EXCEPT:",options:["The business case","The problem statement","The list of verified root causes and selected solutions","The team members and their roles"],answer:2,explanation:"A charter contains the business case, problem and goal statements, scope, metrics, team and milestones. Root causes are verified in Analyze and solutions selected in Improve, so they cannot be in a Define charter.",whyWrong:["The business case is usually a section of the charter. It is tempting because some people think of it as a separate document.","The problem statement is a core charter element.","","The team and roles are part of the charter."]},tempting:0,correctInterpretation:"Treat it as “which one does NOT belong in a charter?”. Three are charter elements; the odd one is the answer.",strategy:"Rewrite EXCEPT as NOT in your head. Tick each option that fits the description; the one left unticked is the answer.",practice:{id:"trap-except-pr",topic:"1.2.3",category:"wording",difficulty:"trap",numerical:!1,traps:["except"],stem:"All of the following are failure costs within the cost of poor quality EXCEPT:",options:["Service credits paid for missed SLAs","Rebuilding a configuration that failed pre-release testing","Handling customer complaints about wrong bills","Training agents on a new, error-proofed order procedure"],answer:3,explanation:"Training to stop errors happening is a prevention cost — an investment in good quality, not a failure cost.",whyWrong:["SLA service credits are an external failure cost.","Rework found before release is an internal failure cost.","Complaint handling is an external failure cost.",""]},highlight:["EXCEPT"]},{id:"least",word:"LEAST",meaning:"Rank the options and pick the one at the bottom of the scale — the weakest fit, least likely or least appropriate.",whyMisread:"Most questions ask for the best or most likely answer, so candidates rank the options correctly but then choose the top one out of habit.",appears:"Which cost is an external failure cost?",actually:"Which cost is the LEAST likely to be classed as an external failure cost?",example:{id:"trap-least-ex",topic:"1.2.3",category:"wording",difficulty:"trap",numerical:!1,traps:["least"],stem:"A managed-services team is classifying its cost of poor quality. Which item is LEAST likely to be classified as an external failure cost?",options:["Service credits paid to an enterprise customer after a P1 restore SLA was missed","A repeat field visit because the first repair did not fix the customer’s fault","Re-testing a firewall change in the staging environment after it failed the internal test","Handling complaints from customers who received an incorrect invoice"],answer:2,explanation:"External failures are found by or affect the customer. The staging re-test happens before the change reaches any customer, so it is an internal failure cost — the least likely to be external.",whyWrong:["Service credits are a clear external failure cost — it is the most likely, not the least likely.","The failed first repair reached the customer, so the repeat visit is external failure. It is tempting because the visit itself looks like “rework”.","","Complaint handling is caused by a defect that reached the customer — external failure."]},tempting:1,correctInterpretation:"Sort the options from most to least external, then take the bottom one.",strategy:"Write a small “+ / –” next to each option for how well it fits, then pick the one with the most minuses. Re-read LEAST before you click.",practice:{id:"trap-least-pr",topic:"1.3.1",category:"wording",difficulty:"trap",numerical:!1,traps:["least"],stem:"Which of the following is LEAST suitable to be run as a DMAIC Green Belt project?",options:["Recurring SLA breaches for P2 incidents whose cause is unknown","A high invoice error rate whose drivers have not been identified","Installing an already-approved software patch on all routers — the fix is known and only needs scheduling","Highly variable fibre installation lead times across regions"],answer:2,explanation:"DMAIC suits problems with an unknown cause that need data to solve. When the solution is already known and approved, it is a “just do it” implementation task, not a DMAIC project.",whyWrong:["Unknown cause and measurable impact — well suited to DMAIC.","Unknown drivers of a measurable defect rate — well suited to DMAIC.","","Variation with unknown causes is a classic DMAIC opportunity."]},highlight:["LEAST"]},{id:"most",word:"MOST",meaning:"Several options may be partly true; choose the one that is the most complete, accurate or likely.",whyMisread:"Candidates stop at the first option that is “not wrong”, without comparing it against a more precise option further down.",appears:"Which statement about Pareto analysis is true?",actually:"Which statement describes the purpose of Pareto analysis MOST accurately?",example:{id:"trap-most-ex",topic:"1.2.4",category:"wording",difficulty:"trap",numerical:!1,traps:["most"],stem:"Which statement MOST accurately describes the purpose of a Pareto analysis in a Define-phase project?",options:["To prove which root cause is responsible for the problem","To identify the vital few categories that account for most of the problem, so the team knows where to focus","To show how the defect rate has changed over time","To confirm that exactly 80% of the defects come from exactly 20% of the causes"],answer:1,explanation:"Pareto analysis ranks categories to show the vital few that contribute most of the effect, helping prioritise and scope the project. It does not prove cause, show trends, or require an exact 80:20 split.",whyWrong:["Tempting because the largest bar often points toward a cause, but Pareto shows where defects cluster; causes are verified with data in Analyze.","","Trends over time need a run chart or control chart, not a Pareto chart.","80:20 is a rule of thumb; the real split may be 70:30 or 90:10."]},tempting:0,correctInterpretation:"Compare all four options and choose the one that is fully accurate, not just partly true.",strategy:"Read all options before answering. Eliminate options that overstate (prove, always, exactly) and choose the most precise remaining statement.",practice:{id:"trap-most-pr",topic:"1.2.5",category:"wording",difficulty:"trap",numerical:!1,traps:["most"],stem:"Which statement MOST accurately describes rolled throughput yield (RTY)?",options:["The average of the first time yields of all process steps","The proportion of good units at the end of the process, including units that were reworked","The probability that a unit passes through every step of the process first time with zero defects","The defects per unit multiplied by the number of opportunities"],answer:2,explanation:"RTY is the product of step FTYs and represents the probability of a unit completing all steps first time without any defect.",whyWrong:["Yields are multiplied, not averaged; an average overstates performance.","That is final yield, which counts reworked units as good.","","DPU × opportunities is not a yield; it is not a meaningful RTY formula."]},highlight:["MOST"]},{id:"best",word:"BEST",meaning:"More than one option could work; choose the one that fits the specific purpose in the stem most directly.",whyMisread:"Candidates pick a familiar, related tool that is useful in general but does not do the specific job asked.",appears:"Which tool is related to customer requirements?",actually:"Which tool is BEST for turning a broad customer need into measurable requirements?",example:{id:"trap-best-ex",topic:"1.2.2",category:"best-tool",difficulty:"trap",numerical:!1,traps:["best"],stem:"Customers tell a broadband provider: “I just want my service to be reliable.” Which tool is BEST for translating this broad need into specific, measurable requirements?",options:["Pareto chart","CTQ tree","Kano model","5S"],answer:1,explanation:"A CTQ tree breaks a broad need into quality drivers and then into measurable CTQs with targets, e.g. “≤ 1 outage per quarter” and “restore within 8 hours”.",whyWrong:["A Pareto chart prioritises categories of a problem; it does not convert a need into requirements.","","Kano classifies needs (basic, performance, delighter) — related and tempting, but it does not make them measurable.","5S organises the workplace; it is unrelated to customer requirements."]},tempting:2,correctInterpretation:"Focus on the exact verb in the stem — “translate into measurable requirements” — and pick the tool designed for that job.",strategy:"Underline the purpose in the stem. For each option ask “Is this tool built for exactly that purpose?”. Related-but-different tools are the usual distractors.",practice:{id:"trap-best-pr",topic:"1.3.1",category:"wording",difficulty:"trap",numerical:!1,traps:["best"],stem:"Which of the following is the BEST goal statement for a project charter?",options:["Improve incident handling as much as possible this year.","Reduce mean time to restore P1 incidents by training the vendor’s L2 engineers.","Reduce mean time to restore P1 incidents from 6.0 hours to 3.0 hours within six months of charter approval.","Mean time to restore P1 incidents is 6.0 hours, causing service credits."],answer:2,explanation:"It names the metric, the baseline, the target and a deadline (SMART) and does not prescribe a solution.",whyWrong:["Not specific, not measurable and has no clear deadline.","It embeds a solution (training) before causes are known — a common trap.","","This is a problem statement, not a goal."]},highlight:["BEST"]},{id:"first",word:"FIRST",meaning:"Several options may all be valid steps; the question asks which comes at the start of the sequence.",whyMisread:"Candidates choose an important or attractive step rather than the earliest one, especially when that step is very visible (cleaning, solutions).",appears:"Which of these is a 5S step?",actually:"Which 5S step is done FIRST in the sequence?",example:{id:"trap-first-ex",topic:"1.4.5",category:"wording",difficulty:"trap",numerical:!1,traps:["first"],stem:"A NOC team is applying 5S to its cluttered operations room and shared drive. Which activity should be done FIRST?",options:["Clean the desks, screens and dashboards and remove stale alerts","Separate needed items and files from unneeded ones and remove the unneeded","Label and arrange the remaining items so they are easy to find","Write a 5S standard and an audit checklist"],answer:1,explanation:"The order is Sort → Straighten → Shine → Standardize → Self-Discipline. Sort comes first: there is no point arranging or cleaning things you do not need.",whyWrong:["That is Shine (third S). Tempting because cleaning feels like the natural start.","","That is Straighten (second S); it comes after Sort.","That is Standardize (fourth S)."]},tempting:0,correctInterpretation:"All four are valid 5S activities; pick the earliest in the official sequence.",strategy:"When you see FIRST, BEFORE or AFTER, quickly write the sequence (S-S-S-S-S or D-M-A-I-C) in the margin and place each option on it.",practice:{id:"trap-first-pr",topic:"1.1.3",category:"dmaic-boundary",difficulty:"trap",numerical:!1,traps:["first"],stem:"A Green Belt has just been assigned a project on late enterprise circuit activations. Which of these should be done FIRST?",options:["Brainstorm and pilot solutions with the provisioning team","Collect baseline data and validate the measurement system","Draft the charter with a problem statement, goal, scope and team","Implement a control chart for activation lead time"],answer:2,explanation:"Drafting the charter is a Define deliverable and comes before Measure (baseline), Improve (solutions) and Control (control charts).",whyWrong:["Solutions belong in Improve; jumping to them first is the classic trap.","This is Measure, which follows Define.","","Control charts belong to the Control phase."]},highlight:["FIRST"]},{id:"primary",word:"PRIMARY",meaning:"Choose the main or most important item — for a project, the metric the goal is built on — not a supporting or side measure.",whyMisread:"Secondary metrics and financial figures are mentioned in the same stem, so candidates pick the one that sounds most important to management (money) or the one mentioned last.",appears:"Which metric is tracked in this project?",actually:"Which metric is the PRIMARY metric — the one the goal statement is trying to move?",example:{id:"trap-primary-ex",topic:"1.3.2",category:"wording",difficulty:"trap",numerical:!1,traps:["primary"],stem:"A project goal reads: “Reduce mean time to restore P1 incidents from 6 hours to 3 hours within six months, without increasing the incident reopen rate, saving an estimated OMR 96,000 per year.” What is the PRIMARY metric?",options:["Incident reopen rate","Estimated annual savings","Mean time to restore P1 incidents","Number of P1 incidents logged"],answer:2,explanation:"The goal is to move mean time to restore from 6 to 3 hours, so that is the primary metric (the project Y).",whyWrong:["The reopen rate is a secondary (consequential) metric — it is watched so it does not get worse. Tempting because it appears in the goal sentence.","Savings are the financial benefit, a consequence of improving the primary metric.","","Incident volume is not the target of this goal."]},tempting:0,correctInterpretation:"Find the metric with a baseline and a target in the goal statement — that is the primary metric.",strategy:"Look for “from X to Y”: the measure attached to the baseline and target is primary. Measures introduced with “without …” are secondary.",practice:{id:"trap-primary-pr",topic:"1.3.2",category:"concept",difficulty:"trap",numerical:!1,traps:["primary"],stem:"What is the PRIMARY purpose of tracking a secondary metric in a Lean Six Sigma project?",options:["To have a backup target in case the primary metric is not achieved","To detect unintended negative effects caused by improving the primary metric","To calculate the financial benefits of the project","To replace the primary metric during the Control phase"],answer:1,explanation:"Secondary (consequential) metrics guard against sub-optimisation, e.g. faster restore times causing more reopened incidents.",whyWrong:["A secondary metric is not a fall-back goal; the project is judged on its primary metric.","","Financial benefits are calculated from the financial metric, not the secondary metric.","The primary metric continues to be monitored in Control."]},highlight:["PRIMARY"]},{id:"before",word:"BEFORE",meaning:"The question is about sequence: which activity must already be complete before a stated point in the process.",whyMisread:"Candidates notice the anchor activity (e.g. “solutions”) and choose an option related to it, even if it happens afterwards.",appears:"Which activity is related to selecting solutions?",actually:"Which activity must be completed BEFORE solutions are selected?",example:{id:"trap-before-ex",topic:"1.1.3",category:"dmaic-boundary",difficulty:"trap",numerical:!1,traps:["before"],stem:"In a DMAIC project, which activity should be completed BEFORE solutions are selected and piloted?",options:["Develop the control plan and response plan","Verify the root causes with data","Hand the process over to the process owner","Calculate the realized financial benefits"],answer:1,explanation:"Root causes are verified in Analyze, which precedes Improve, where solutions are selected and piloted.",whyWrong:["The control plan is built after the solution is chosen (Improve/Control). Tempting because it is closely linked to solutions.","","Handover happens at the end of Control.","Realized benefits can only be measured after implementation."]},tempting:0,correctInterpretation:"Locate the anchor (solution selection = Improve) on the DMAIC timeline and choose the option that sits earlier.",strategy:"Draw an arrow D→M→A→I→C. Mark the anchor, then cross out every option to its right.",practice:{id:"trap-before-pr",topic:"1.2.5",category:"wording",difficulty:"trap",numerical:!1,traps:["before"],stem:"Which must be agreed BEFORE a team can calculate DPMO for its invoicing process?",options:["The sigma level of the process","The rolled throughput yield of all billing steps","The number of opportunities per invoice and an operational definition of a defect","The control limits for the invoice error chart"],answer:2,explanation:"DPMO = defects ÷ (units × opportunities) × 1,000,000, so the opportunities per unit and the defect definition must be fixed first.",whyWrong:["The sigma level is looked up from DPMO, so it comes after.","RTY is a separate metric and is not needed for DPMO.","","Control limits come later and are unrelated to the DPMO calculation."]},highlight:["BEFORE"]},{id:"after",word:"AFTER",meaning:"The question asks what follows a stated point — the next phase, the next step, or who is responsible once something has ended.",whyMisread:"Candidates pick an activity from the phase named in the stem (the anchor) rather than from the phase that follows it.",appears:"Which activity belongs to the Measure phase?",actually:"Which activity comes immediately AFTER the Measure phase?",example:{id:"trap-after-ex",topic:"1.1.3",category:"dmaic-boundary",difficulty:"trap",numerical:!1,traps:["after"],stem:"Which activity takes place in the DMAIC phase that comes immediately AFTER Measure?",options:["Establishing the baseline performance of the process","Identifying and verifying the root causes of the problem","Selecting and piloting solutions","Writing the problem statement and project scope"],answer:1,explanation:"Analyze follows Measure, and its key deliverable is identifying and verifying root causes (the critical X’s).",whyWrong:["Establishing the baseline is the Measure phase itself — tempting because it is the anchor named in the stem.","","Solutions are selected in Improve, two phases after Measure.","The problem statement and scope are written in Define, before Measure."]},tempting:0,correctInterpretation:"Move one step to the right of the anchor phase on D-M-A-I-C and choose that phase’s activity.",strategy:"Say the sequence aloud and point to the anchor, then step once in the direction the word tells you.",practice:{id:"trap-after-pr",topic:"1.1.6",category:"wording",difficulty:"trap",numerical:!1,traps:["after"],stem:"AFTER a Lean Six Sigma project has been closed and handed over, who is primarily responsible for sustaining the improved performance?",options:["The Green Belt who led the project","The process owner","The Master Black Belt","The finance representative"],answer:1,explanation:"The process owner accepts the control plan at handover and is accountable for the day-to-day performance of the process afterwards.",whyWrong:["The Belt leads the project but moves on after closure — the tempting choice because they “own” the project.","","The MBB coaches Belts; they do not run the process.","Finance validates benefits; it does not run the process."]},highlight:["AFTER"]},{id:"without-rework",word:"WITHOUT REWORK",meaning:"Count only units that passed correctly the first time. Units that were fixed and then passed do NOT count. This is first time yield (FTY).",whyMisread:"Candidates count all good units at the end (final yield), because reworked units look “good” in the final output.",appears:"What proportion of units ended up good?",actually:"What proportion passed first time, WITHOUT REWORK (FTY)?",example:{id:"trap-without-rework-ex",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["without-rework"],stem:"In one week, 500 new-line orders enter the provisioning step. 420 are completed correctly the first time, 60 are returned, corrected and then completed, and 20 are cancelled as unrecoverable. What proportion of orders passed WITHOUT REWORK?",options:["84%","96%","87.5%","12%"],answer:0,explanation:"FTY = units passing first time without rework ÷ units entering = 420 ÷ 500 = 0.84 = 84%. The 60 reworked orders are excluded from the numerator.",whyWrong:["","That is final yield: (420 + 60) ÷ 500 = 480 ÷ 500 = 96%. It counts reworked orders as good.","420 ÷ 480 = 87.5% uses the wrong denominator — FTY divides by all units entering (500).","60 ÷ 500 = 12% is the rework rate, not the yield."]},tempting:1,correctInterpretation:"Numerator = first-time passes only (420); denominator = all units entering (500).",strategy:"Split the units into three buckets — first-time good, reworked, scrapped — and use only the first bucket for FTY. Final yield = first-time good + reworked.",practice:{id:"trap-without-rework-pr",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["without-rework"],stem:"1,200 change requests are submitted to the CAB in a quarter. 1,020 are approved on first submission, 150 are sent back for correction and then approved, and 30 are rejected. What is the first time yield, i.e. the share approved WITHOUT REWORK?",options:["85.0%","97.5%","87.2%","12.5%"],answer:0,explanation:"FTY = 1,020 ÷ 1,200 = 0.85 = 85.0%.",whyWrong:["","That is final yield: (1,020 + 150) ÷ 1,200 = 1,170 ÷ 1,200 = 97.5%.","1,020 ÷ 1,170 ≈ 87.2% uses only the approved requests as the denominator.","150 ÷ 1,200 = 12.5% is the rework rate."]},highlight:["WITHOUT REWORK"]},{id:"first-pass",word:"FIRST PASS",meaning:"Use first-pass (first time) yields — never final yields. Across several steps, “all steps first pass” means RTY: multiply the step FTYs.",whyMisread:"Tables often show both first-pass and final yields. Candidates grab the larger final yields, or average the step yields instead of multiplying.",appears:"What is the overall yield of the process?",actually:"What is the probability that a unit passes ALL steps FIRST PASS — the product of step FTYs (RTY)?",example:{id:"trap-first-pass-ex",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["first-pass"],stem:`A ticket passes through three steps:

| Step | First pass yield | Final yield (after rework) |
|---|---|---|
| Logging | 0.95 | 0.99 |
| Diagnosis | 0.90 | 0.98 |
| Resolution | 0.98 | 1.00 |

What is the probability that a ticket goes through all three steps FIRST PASS, with no rework at any step?`,options:["83.8%","97.0%","94.3%","90.0%"],answer:0,explanation:"RTY = 0.95 × 0.90 × 0.98 = 0.8379 ≈ 83.8%.",whyWrong:["","0.99 × 0.98 × 1.00 = 0.9702 ≈ 97.0% multiplies the final yields, which include rework.","(0.95 + 0.90 + 0.98) ÷ 3 ≈ 94.3% averages the yields — RTY must multiply.","90.0% is just the lowest step FTY; RTY is always at or below the lowest step."]},tempting:1,correctInterpretation:"Pick the first-pass column and multiply every step’s value.",strategy:"Cross out the final-yield column immediately. Sanity check: RTY must be less than or equal to the smallest step FTY.",practice:{id:"trap-first-pass-pr",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["first-pass"],stem:"An order-to-activation process has four steps with first pass yields of 0.97, 0.92, 0.88 and 0.99. What is the rolled throughput yield — the chance an order completes every step first pass?",options:["77.7%","94.0%","88.0%","22.3%"],answer:0,explanation:"RTY = 0.97 × 0.92 × 0.88 × 0.99 = 0.77745888 ≈ 77.7%.",whyWrong:["","(0.97 + 0.92 + 0.88 + 0.99) ÷ 4 = 0.94 averages the yields instead of multiplying.","88.0% is the lowest single step, not the combined probability.","1 − 0.777 ≈ 22.3% is the probability that an order needs rework somewhere — the complement of RTY."]},highlight:["FIRST PASS"]},{id:"total-defects",word:"TOTAL DEFECTS",meaning:"Count every defect, including several on the same unit. DPU uses total defects in the numerator, not the number of defective units.",whyMisread:"Stems usually give both “units with errors” and “errors found”. Candidates use the defective-unit count because it is mentioned first.",appears:"How many invoices had a problem, per invoice?",actually:"How many TOTAL DEFECTS were found, per invoice (DPU)?",example:{id:"trap-total-defects-ex",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["total-defects"],stem:"An audit of 200 customer invoices finds that 30 invoices contain errors, with 45 TOTAL DEFECTS found across those 30 invoices. What is the defects per unit (DPU)?",options:["0.225","0.15","1.5","0.667"],answer:0,explanation:"DPU = total defects ÷ total units = 45 ÷ 200 = 0.225.",whyWrong:["","30 ÷ 200 = 0.15 is the proportion defective (defective units), not DPU.","45 ÷ 30 = 1.5 is defects per defective invoice — the denominator must be all 200 units.","30 ÷ 45 ≈ 0.667 has no meaning as a quality metric here."]},tempting:1,correctInterpretation:"Numerator = all defects (45); denominator = all units inspected (200).",strategy:"Label every number in the stem: “units inspected”, “defective units”, “defects”. DPU always uses defects ÷ units inspected.",practice:{id:"trap-total-defects-pr",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["total-defects"],stem:"A depot inspects 250 refurbished routers. It records 20 scratched casings, 15 missing labels and 5 wrong firmware versions; these defects are found on 32 routers. What is the DPU?",options:["0.16","0.128","0.8","6.25"],answer:0,explanation:"Total defects = 20 + 15 + 5 = 40. DPU = 40 ÷ 250 = 0.16.",whyWrong:["","32 ÷ 250 = 0.128 uses defective units instead of total defects.","32 ÷ 40 = 0.8 divides defective units by defects.","250 ÷ 40 = 6.25 inverts the formula."]},highlight:["TOTAL DEFECTS"]},{id:"defective-units",word:"DEFECTIVE UNITS",meaning:"Count units that have at least one defect, each counted once, however many defects it has.",whyMisread:"The defect count is usually larger and more prominent, so candidates divide total defects by units and report that as “percent defective”.",appears:"How many defects per order were there?",actually:"What proportion of orders were DEFECTIVE UNITS (had at least one defect)?",example:{id:"trap-defective-units-ex",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["defective-units"],stem:"Out of 400 SIM activation orders, 52 errors are found. The errors are spread across 40 orders; the other orders are error-free. What percentage of the orders are DEFECTIVE UNITS?",options:["10%","13%","76.9%","1.3%"],answer:0,explanation:"Percent defective = defective units ÷ total units = 40 ÷ 400 = 0.10 = 10%.",whyWrong:["","52 ÷ 400 = 0.13 is DPU expressed as a percentage — it counts defects, not defective units.","40 ÷ 52 ≈ 76.9% mixes defective units with defects.","1.3% comes from misplacing the decimal of 52 ÷ 400."]},tempting:1,correctInterpretation:"Numerator = units with at least one error (40); denominator = all units (400).",strategy:"When you see “defective”, think “how many units are bad?” — a yes/no per unit. Percent defective can never exceed 100%.",practice:{id:"trap-defective-units-pr",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["defective-units"],stem:"A quality check of 800 closed incident tickets finds 96 documentation defects in 72 tickets. What proportion of tickets were defective units?",options:["9%","12%","75%","91%"],answer:0,explanation:"Proportion defective = 72 ÷ 800 = 0.09 = 9%.",whyWrong:["","96 ÷ 800 = 0.12 is DPU, using defects instead of defective tickets.","72 ÷ 96 = 75% has no useful meaning here.","91% is the proportion of tickets without defects (728 ÷ 800)."]},highlight:["DEFECTIVE UNITS"]},{id:"per-opportunity",word:"PER OPPORTUNITY",meaning:"The denominator is the total number of opportunities = units × opportunities per unit. DPO = defects ÷ opportunities; DPMO = DPO × 1,000,000.",whyMisread:"Candidates divide by units only (DPU) and then multiply by a million, forgetting the opportunities per unit.",appears:"Defects per unit, scaled to a million?",actually:"Defects PER OPPORTUNITY, scaled to a million (units × opportunities in the denominator).",example:{id:"trap-per-opportunity-ex",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["per-opportunity"],stem:"A service desk audits 1,000 service requests. Each request has 5 opportunities for a defect (category, priority, contact details, resolution note, closure code). 75 defects are found. What are the defects PER OPPORTUNITY, expressed per million (DPMO)?",options:["15,000","75,000","0.075","1,500"],answer:0,explanation:"Opportunities = 1,000 × 5 = 5,000. DPO = 75 ÷ 5,000 = 0.015. DPMO = 0.015 × 1,000,000 = 15,000.",whyWrong:["","75 ÷ 1,000 × 1,000,000 = 75,000 uses DPU, ignoring the 5 opportunities per request.","75 ÷ 1,000 = 0.075 is DPU, not DPMO.","1,500 is a factor-of-ten slip in the scaling."]},tempting:1,correctInterpretation:"Denominator = 1,000 × 5 = 5,000 opportunities, then scale to a million.",strategy:"Write DPMO = D ÷ (U × O) × 10⁶ before substituting. Check: DPMO should be smaller than DPU × 10⁶ whenever there is more than one opportunity per unit.",practice:{id:"trap-per-opportunity-pr",topic:"1.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["per-opportunity"],stem:"A billing team checks 2,500 invoices on 8 fields each. It finds 120 field errors. What is the DPMO?",options:["6,000","48,000","0.006","600"],answer:0,explanation:"Opportunities = 2,500 × 8 = 20,000. DPO = 120 ÷ 20,000 = 0.006. DPMO = 0.006 × 1,000,000 = 6,000.",whyWrong:["","120 ÷ 2,500 × 1,000,000 = 48,000 uses DPU and ignores the 8 opportunities.","0.006 is DPO — it has not been scaled to a million.","600 is a scaling slip by a factor of ten."]},highlight:["PER OPPORTUNITY"]},{id:"cumulative-percentage",word:"CUMULATIVE PERCENTAGE",meaning:"The running total of the sorted categories up to and including the one asked about, divided by the grand total.",whyMisread:"Candidates give the category’s own share (its bar) instead of the running total (the line), or forget to sort the categories first.",appears:"What percentage of tickets are billing queries?",actually:"What is the CUMULATIVE PERCENTAGE reached at the billing-query bar — that bar plus all bars before it?",example:{id:"trap-cumulative-percentage-ex",topic:"1.2.4",category:"chart",difficulty:"trap",numerical:!0,traps:["cumulative-percentage"],stem:"A service desk logs 400 repeat tickets in a month: Password resets 180, Network outage 120, Billing query 60, Email configuration 25, Printer faults 15. On a Pareto chart, what is the CUMULATIVE PERCENTAGE at the “Billing query” bar?",options:["90%","15%","75%","60%"],answer:0,explanation:"Sorted descending: 180 (45%), 120 (30%, cumulative 75%), 60 (15%, cumulative 90%). (180 + 120 + 60) ÷ 400 = 360 ÷ 400 = 90%.",whyWrong:["","60 ÷ 400 = 15% is the billing bar’s own share, not the cumulative value.","75% is the cumulative value at the previous bar (Network outage).","60% confuses the count (60) with a percentage."],chart:{type:"pareto",labels:["Password resets","Network outage","Billing query","Email configuration","Printer faults"],values:[180,120,60,25,15]}},tempting:1,correctInterpretation:"Sort, add the counts up to and including the target bar, and divide by the total.",strategy:"Write a running-total column next to the sorted counts. The cumulative line only ever rises and ends at 100%.",practice:{id:"trap-cumulative-percentage-pr",topic:"1.2.4",category:"chart",difficulty:"trap",numerical:!0,traps:["cumulative-percentage"],stem:"Billing complaints for a quarter: Wrong tariff 30, Late activation charge 110, Duplicate charge 50, Address error 10. Using a Pareto chart, which categories are needed for the cumulative percentage to reach at least 80%?",options:["Late activation charge and Duplicate charge","Late activation charge only","Late activation charge, Duplicate charge and Wrong tariff","Wrong tariff and Duplicate charge"],answer:0,explanation:"Total = 200. Sorted: Late activation 110 (55%), Duplicate charge 50 (25%, cumulative 80%), Wrong tariff 30 (cumulative 95%), Address error 10 (cumulative 100%). Two categories reach 80%.",whyWrong:["","Late activation alone is 110 ÷ 200 = 55%, below 80%. Tempting because it is the largest bar.","Three categories reach 95%; the question asks for the categories needed to reach 80%, which happens at the second bar.","This uses the unsorted order; Pareto must be sorted from largest to smallest."],chart:{type:"pareto",labels:["Wrong tariff","Late activation charge","Duplicate charge","Address error"],values:[30,110,50,10]}},highlight:["CUMULATIVE PERCENTAGE"]},{id:"verified-root-cause",word:"VERIFIED ROOT CAUSE",meaning:"A cause that has been confirmed with data, typically in the Analyze phase. Suspected causes from brainstorming or opinion are not verified.",whyMisread:"Candidates treat team agreement, the biggest Pareto bar or a manager’s opinion as proof, or assume the cause is known in Define.",appears:"What do we think is causing the problem?",actually:"Has the cause been VERIFIED with data — and in which phase does that happen?",example:{id:"trap-verified-root-cause-ex",topic:"1.1.3",category:"dmaic-boundary",difficulty:"trap",numerical:!1,traps:["verified-root-cause"],stem:"At the Define tollgate, the sponsor asks the Green Belt to present the VERIFIED ROOT CAUSE of late fibre installations. What is the most appropriate response?",options:["Present the cause the team agreed on during the kick-off brainstorm, because team consensus verifies it","Present the largest bar of the Pareto chart of delay reasons as the verified root cause","Explain that root causes are verified with data in the Analyze phase; Define provides the problem, goal, scope and team","Skip to Improve so a solution can be tested quickly, then confirm the cause afterwards"],answer:2,explanation:"Define frames the problem; root causes are identified and verified with data in Analyze. Presenting a “verified” root cause in Define would be jumping to conclusions.",whyWrong:["Brainstorming produces potential causes; agreement among the team is not data-based verification. This is the most tempting option.","A Pareto chart shows where the problem concentrates, not why it happens.","","Jumping to solutions without verified causes risks fixing the wrong thing."]},tempting:0,correctInterpretation:"A verified root cause requires data analysis, which belongs to Analyze — not to Define or brainstorming.",strategy:"Whenever a stem says “verified”, “confirmed” or “proven”, ask “What data proved it, and in which phase?”. Opinion and consensus are never verification.",practice:{id:"trap-verified-root-cause-pr",topic:"1.1.3",category:"dmaic-boundary",difficulty:"trap",numerical:!1,traps:["verified-root-cause"],stem:"In which DMAIC phase is a list of verified root causes (critical X’s) a key deliverable?",options:["Define","Measure","Analyze","Improve"],answer:2,explanation:"Analyze identifies potential X’s and verifies with data which ones actually drive the Y.",whyWrong:["Define frames the problem, goal and scope; causes are not verified yet.","Measure establishes the baseline and validates measurement; it may list potential X’s but does not verify them. Tempting because data collection happens here.","","Improve uses the verified causes to design solutions."]},highlight:["VERIFIED ROOT CAUSE"]},{id:"estimated-benefits",word:"ESTIMATED BENEFITS",meaning:"A forecast of the gain if the goal is achieved, prepared in Define for the business case. It is not money already saved.",whyMisread:"Candidates treat an approved estimate as an achieved result, or confuse it with the full baseline cost of the problem.",appears:"How much has the project saved?",actually:"What is the ESTIMATED (forecast) benefit stated in the business case — and how should it be treated?",example:{id:"trap-estimated-benefits-ex",topic:"1.3.3",category:"business-case",difficulty:"trap",numerical:!1,traps:["estimated-benefits"],stem:"A newly approved charter for reducing SLA service credits states ESTIMATED BENEFITS of OMR 96,000 per year. Which statement is correct?",options:["The OMR 96,000 can be reported as savings achieved, because the charter has been signed","It is a forecast based on the baseline cost and the goal; it should be reviewed with Finance and later confirmed as realized benefits after implementation","Estimated benefits are optional and are normally calculated only in the Control phase","It represents the total annual cost of the problem, so the project must eliminate all service credits"],answer:1,explanation:"Estimated benefits size and justify the project in Define. They are only a projection until results are measured after implementation and validated (realized benefits).",whyWrong:["Signing the charter approves the project; it does not deliver savings. This is the tempting misreading.","","Benefits are estimated in Define to support the business case; Control confirms realized benefits.","The baseline cost (COPQ) and the estimated benefit are different; the goal may remove only part of the cost."]},tempting:0,correctInterpretation:"Estimated = forecast in Define; it guides the decision but has not been achieved.",strategy:"Ask “Has the improvement actually been implemented and measured?”. If not, any figure is an estimate. Estimated benefit = baseline cost × expected reduction over the period.",practice:{id:"trap-estimated-benefits-pr",topic:"1.3.3",category:"calculation",difficulty:"trap",numerical:!0,traps:["estimated-benefits"],stem:"Baseline SLA service credits are OMR 20,000 per month. The project goal is to reduce them by 40%. What are the estimated annual benefits to state in the business case?",options:["OMR 96,000","OMR 8,000","OMR 240,000","OMR 144,000"],answer:0,explanation:"Monthly saving = 20,000 × 0.40 = 8,000. Annual estimate = 8,000 × 12 = OMR 96,000.",whyWrong:["","OMR 8,000 is the monthly figure; the question asks for annual.","OMR 240,000 (20,000 × 12) is the annual baseline cost, not the benefit.","OMR 144,000 (60% of 240,000) is the cost that would remain after the improvement."]},highlight:["ESTIMATED BENEFITS"]},{id:"realized-benefits",word:"REALIZED BENEFITS",meaning:"Benefits actually achieved and measured after implementation, over the real elapsed period, against the baseline — ideally validated by Finance.",whyMisread:"Candidates repeat the original estimate, or annualise a short run of results as if the full year had already happened.",appears:"How much will the project save?",actually:"How much has the project REALIZED so far, based on actual measured results?",example:{id:"trap-realized-benefits-ex",topic:"1.3.3",category:"calculation",difficulty:"trap",numerical:!0,traps:["realized-benefits"],stem:"A project estimated benefits of OMR 96,000 per year. Six months after implementation, Finance confirms that monthly SLA service credits fell from a baseline of OMR 20,000 to OMR 14,000 and stayed there. What are the REALIZED BENEFITS to date?",options:["OMR 36,000","OMR 96,000","OMR 48,000","OMR 72,000"],answer:0,explanation:"Actual monthly saving = 20,000 − 14,000 = 6,000. Over the 6 months measured: 6,000 × 6 = OMR 36,000 realized.",whyWrong:["","OMR 96,000 is the original annual estimate, not what was actually achieved. This is the tempting answer.","OMR 48,000 is half the estimate; it assumes the estimate was achieved instead of using the measured saving.","OMR 72,000 (6,000 × 12) is an annualised run rate — a projection, not benefits realized to date."]},tempting:1,correctInterpretation:"Use measured performance versus baseline, for the period that has actually elapsed.",strategy:"Ignore the estimate when asked for realized benefits. Compute (baseline − actual) × periods elapsed, and check who validated it.",practice:{id:"trap-realized-benefits-pr",topic:"1.3.3",category:"wording",difficulty:"trap",numerical:!1,traps:["realized-benefits"],stem:"Which evidence BEST supports a claim of realized benefits at project closure?",options:["The estimated benefit figure in the approved business case","A survey showing that the team believes the process is better","Finance-validated comparison of actual post-implementation costs with the baseline over a defined period","The number of solutions that were implemented"],answer:2,explanation:"Realized benefits are demonstrated by measured results compared with the baseline over time, validated independently (usually by Finance).",whyWrong:["The business case figure is an estimate made before implementation.","Opinions are not measured financial results.","","Implementing solutions does not prove they delivered benefits."]},highlight:["REALIZED BENEFITS"]},{id:"sample-vs-population",word:"SAMPLE vs POPULATION",meaning:"Sample statistics (x̄, s) estimate population parameters (μ, σ). A sample standard deviation divides by n − 1; a population standard deviation divides by N.",whyMisread:"Calculators offer both σn and σn−1 buttons, and “standard deviation” sounds like one thing. Candidates press the wrong key or write hypotheses about x̄ instead of μ.",appears:"Calculate the standard deviation of these numbers.",actually:"These numbers are a SAMPLE drawn from a larger process — use the n − 1 formula to estimate the process standard deviation.",example:{id:"trap-sample-vs-population-ex",topic:"2.2.1",category:"calculation",difficulty:"trap",numerical:!0,traps:["sample-vs-population"],stem:"A Green Belt takes a random SAMPLE of 5 P2 incidents from last quarter to estimate the variation of the whole restore process. Restore times (hours): 3, 5, 4, 6, 7. What is the best estimate of the process standard deviation?",options:["1.41 hours","1.58 hours","2.50 hours","2.00 hours"],answer:1,explanation:"Mean = 25 ÷ 5 = 5. Squared deviations: 4 + 0 + 1 + 1 + 4 = 10. Because the data are a sample, divide by n − 1 = 4: s² = 2.5, so s = √2.5 ≈ 1.58 hours.",whyWrong:["1.41 = √(10 ÷ 5) uses the population formula (divide by N). It underestimates the process spread when you only have a sample — the tempting calculator-key mistake.","","2.50 is the sample VARIANCE (hours²), not the standard deviation.","2.00 is the population variance (10 ÷ 5) — wrong formula and wrong units."]},tempting:0,correctInterpretation:"Ask “is this every item, or a subset used to estimate something bigger?”. Almost always in Six Sigma it is a sample: use s with n − 1, and state hypotheses about μ, σ, p (parameters).",strategy:"Look for the words “sample”, “randomly selected”, “estimate”. Write s = √[Σ(x − x̄)² ÷ (n − 1)] in your notepad before computing. On the exam calculator, check whether it reports sx (n − 1) or σx (n).",practice:{id:"trap-sample-vs-population-pr",topic:"2.2.1",category:"concept",difficulty:"trap",numerical:!1,traps:["sample-vs-population"],stem:"A team wants to test whether the average handle time of ALL calls under the new script differs from 300 seconds, using 40 sampled calls. Which null hypothesis is written correctly?",options:["H₀: x̄ = 300 s","H₀: μ = 300 s","H₀: s = 300 s","H₀: x̄ ≠ 300 s"],answer:1,explanation:"Hypotheses are statements about population parameters. The population mean is μ, so H₀: μ = 300 s. The sample mean x̄ is what we calculate from the 40 calls to test it.",whyWrong:["x̄ is a sample statistic — we already know its value; there is nothing to test about it. This is the tempting notation slip.","","s is the sample standard deviation, not the mean.","Uses a statistic and puts “≠” in the null; the null always holds the equality."]},highlight:["SAMPLE"]},{id:"short-vs-long-term",word:"SHORT-TERM vs LONG-TERM",meaning:"Short-term (within-subgroup) σ is used for Cp and Cpk; long-term (overall) σ, which includes shifts and drifts over time, is used for Pp and Ppk.",whyMisread:"Both standard deviations are given in the stem and the formulas look identical. Candidates grab the first σ they see.",appears:"Calculate the capability index.",actually:"Choose the σ that matches the index: within/short-term for Cp/Cpk; overall/long-term for Pp/Ppk.",example:{id:"trap-short-vs-long-term-ex",topic:"2.4.1",category:"calculation",difficulty:"trap",numerical:!0,traps:["short-vs-long-term"],stem:"Fibre splice loss has LSL = 90 and USL = 110 (scaled units). Six months of data give a mean of 103, a within-subgroup (short-term) σ of 2.0 and an overall (LONG-TERM) σ of 2.5. What is Ppk — the long-term actual performance index?",options:["1.17","0.93","1.33","1.67"],answer:1,explanation:"Ppk uses the overall σ: Ppk = min(USL − mean, mean − LSL) ÷ 3σ(overall) = min(110 − 103, 103 − 90) ÷ (3 × 2.5) = 7 ÷ 7.5 ≈ 0.93.",whyWrong:["1.17 = 7 ÷ (3 × 2.0) is Cpk — it uses the short-term σ. This is the tempting mix-up.","","1.33 = 20 ÷ (6 × 2.5) is Pp — right σ, but it ignores centring.","1.67 = 20 ÷ (6 × 2.0) is Cp — wrong σ and ignores centring."]},tempting:0,correctInterpretation:"P = Performance = overall data = LONG-TERM σ. C = Capability = within subgroups = SHORT-TERM σ.",strategy:"Write a 2×2 grid in your notepad: rows Cp/Cpk (within σ) and Pp/Ppk (overall σ); columns “spread only” (p) and “spread + centring” (pk). Place the requested index before calculating.",practice:{id:"trap-short-vs-long-term-pr",topic:"2.4.1",category:"concept",difficulty:"trap",numerical:!1,traps:["short-vs-long-term"],stem:"A process shows Cpk = 1.45 but Ppk = 0.82 over the same six-month study. What is the MOST likely explanation?",options:["The measurement system has poor repeatability","The process shifts or drifts between subgroups over time, so long-term variation is much larger than short-term variation","The specification limits are too wide","The process is perfectly centred"],answer:1,explanation:"Cpk uses within-subgroup σ; Ppk uses overall σ. A large gap means variation BETWEEN subgroups (shifts, drifts, shift-to-shift differences) inflates the overall σ. Stabilising the process over time would move Ppk toward Cpk.",whyWrong:["Poor repeatability would inflate both within and overall σ, not create a large gap between them.","","Wider specs would raise both indices equally.","Centring affects the “k” part of both indices equally; it does not explain the gap."]},highlight:["LONG-TERM"]},{id:"cp-vs-cpk",word:"Cp vs Cpk",meaning:"Cp measures only whether the spread fits within the specification width. Cpk also accounts for where the process is centred, using the distance to the NEAREST limit.",whyMisread:"Cp is easier to calculate (one subtraction) and appears first in most tables, so candidates compute Cp when the question asks for Cpk — or the reverse.",appears:"How capable is the process?",actually:"Is the question asking for potential (Cp — ignoring centring) or actual (Cpk — including centring)?",example:{id:"trap-cp-vs-cpk-ex",topic:"2.4.1",category:"calculation",difficulty:"trap",numerical:!0,traps:["cp-vs-cpk"],stem:"Service activation time has LSL = 20 min and USL = 60 min. A stable process has mean 48 min and within-subgroup σ = 5 min. What is Cpk?",options:["1.33","1.87","0.80","0.40"],answer:2,explanation:"Cpk = min(USL − mean, mean − LSL) ÷ 3σ = min(60 − 48, 48 − 20) ÷ 15 = min(12, 28) ÷ 15 = 0.80. (Cp would be 40 ÷ 30 = 1.33 — the process COULD be capable if centred at 40.)",whyWrong:["1.33 = (60 − 20) ÷ (6 × 5) is Cp. It ignores that the mean sits close to the USL — the tempting answer.","1.87 = 28 ÷ 15 uses the FARTHER limit (CPL). Cpk takes the minimum, i.e. the nearer limit.","","0.40 = 12 ÷ 30 divides by 6σ instead of 3σ."]},tempting:0,correctInterpretation:"Cpk = the worse side. Find the specification limit closest to the mean, take that distance and divide by 3σ.",strategy:"Sketch a number line with LSL, mean and USL. Measure to the nearer limit; divide by 3σ for Cpk, but use the full width ÷ 6σ for Cp. Remember Cpk ≤ Cp always.",practice:{id:"trap-cp-vs-cpk-pr",topic:"2.4.1",category:"concept",difficulty:"trap",numerical:!1,traps:["cp-vs-cpk"],stem:"A process has Cp = 1.60 and Cpk = 0.70. Which improvement action should come FIRST?",options:["Reduce the process variation — the spread is too wide","Widen the specification limits","Shift the process mean toward the centre of the specification","Nothing — Cp above 1.33 shows the process is capable"],answer:2,explanation:"Cp = 1.60 shows the spread already fits comfortably. The big gap to Cpk = 0.70 means the process is off-centre. Re-centring is the quickest way to raise Cpk toward 1.60.",whyWrong:["Spread is fine (Cp = 1.60); reducing it is harder and not the main issue.","Specifications come from the customer; changing them is not a process improvement.","","Cp ignores centring. With Cpk = 0.70 many units fall outside the nearer limit — the tempting misreading."]},highlight:["Cpk"]},{id:"spec-vs-control-limits",word:"SPECIFICATION vs CONTROL LIMITS",meaning:"Specification limits are the voice of the customer (what is acceptable). Control limits are the voice of the process (what the stable process normally does), calculated from data.",whyMisread:"Both are horizontal lines with “upper” and “lower” in their names. Candidates judge stability against the SLA, or judge customer acceptability against the UCL.",appears:"Is this result acceptable?",actually:"Is the question about the customer requirement (spec) or about process stability (control limits)? They are answered separately.",example:{id:"trap-spec-vs-control-limits-ex",topic:"5.2.1",category:"scenario",difficulty:"trap",numerical:!1,traps:["spec-vs-control-limits"],stem:"An I chart of daily P1 MTTR has centre line 4.2 h, UCL 5.8 h and LCL 2.6 h. The contractual SLA is 8 h. Yesterday’s value was 6.4 h. What should the team conclude?",options:["No action is needed because 6.4 h is inside the 8-hour SLA","The point is above the UCL, so it signals a special cause that should be investigated under the response plan, even though the SLA was met","The control limits should be widened to 8 h to match the SLA","The process is not capable and must be redesigned"],answer:1,explanation:"Stability is judged against control limits: 6.4 h is above the UCL of 5.8 h, which is a special-cause signal. Meeting the 8 h specification does not make the process stable; investigating now prevents a future SLA breach.",whyWrong:["This judges a stability signal against the specification — the tempting confusion. The SLA tells you the customer outcome, not whether the process changed.","","Control limits are calculated from process data; they are never set equal to specification limits.","One special-cause point says nothing about capability; capability is assessed once the process is stable."]},tempting:0,correctInterpretation:"Two separate questions: (1) Is the process stable? → compare with control limits. (2) Is the output acceptable? → compare with specification limits.",strategy:"Label each line in the stem as “VOC (spec)” or “VOP (control)” before reading the options. Never draw spec limits on an X-bar chart — they apply to individual units, not averages.",practice:{id:"trap-spec-vs-control-limits-pr",topic:"5.2.1",category:"incorrect-statement",difficulty:"trap",numerical:!1,traps:["spec-vs-control-limits"],stem:"Which statement about control limits is correct?",options:["They are set by the customer or contract","They are calculated from the process’s own data, typically ±3 standard errors of the plotted statistic from the centre line","A process inside its control limits is always meeting specification","They should be recalculated after every new data point"],answer:1,explanation:"Control limits come from process data and describe common-cause variation of the plotted statistic. They are independent of specifications and are recalculated only after a verified process change.",whyWrong:["That describes specification limits — the tempting mix-up.","","A stable process can be consistently producing out-of-spec results (stable but not capable).","Constantly recalculating limits absorbs special causes into the limits and hides signals."]},highlight:["UCL","SLA"]},{id:"accuracy-vs-precision",word:"ACCURATE vs PRECISE",meaning:"Accuracy = average reading close to the true value (bias). Precision = repeated readings close to each other (spread).",whyMisread:"In everyday English the words are used interchangeably, and tightly grouped readings “look” trustworthy.",appears:"Which measurement tool is better?",actually:"Which tool is closer to the truth ON AVERAGE (accuracy), or which gives more consistent readings (precision)?",example:{id:"trap-accuracy-vs-precision-ex",topic:"2.3.1",category:"compare",difficulty:"trap",numerical:!1,traps:["accuracy-vs-precision"],stem:"A reference link has a true latency of 100.0 ms. Probe A, measuring it 20 times, averages 104.0 ms with a standard deviation of 0.5 ms. Probe B averages 100.2 ms with a standard deviation of 3.0 ms. Which probe is more ACCURATE?",options:["Probe A, because its readings vary much less","Probe B, because its average is much closer to the true value","Both are equally accurate because both were measured 20 times","Neither can be judged without a Gage R&R study"],answer:1,explanation:"Accuracy concerns bias: A is off by +4.0 ms, B by only +0.2 ms, so B is more accurate. A is more PRECISE (SD 0.5 vs 3.0) — but precisely wrong.",whyWrong:["Low spread is precision, not accuracy — the tempting answer. A has a large bias of +4 ms.","","The number of readings does not determine accuracy.","Gage R&R assesses precision (repeatability and reproducibility); accuracy is assessed with a bias study against a reference, which is what the data already show."]},tempting:0,correctInterpretation:"Accuracy → compare the AVERAGE with the reference. Precision → look at the SPREAD of repeated readings.",strategy:"Picture a dartboard: accuracy = centre of the cluster on the bull’s-eye; precision = darts close together. Fix accuracy by calibration; fix precision by improving the gauge or method.",practice:{id:"trap-accuracy-vs-precision-pr",topic:"2.3.2",category:"concept",difficulty:"trap",numerical:!1,traps:["accuracy-vs-precision"],stem:"Which of the following is a component of measurement ACCURACY rather than precision?",options:["Repeatability","Reproducibility","Linearity","Number of distinct categories"],answer:2,explanation:"Accuracy components are bias, linearity (bias across the range) and stability (bias over time). Repeatability, reproducibility and ndc describe precision.",whyWrong:["Repeatability is a precision component (within-appraiser spread).","Reproducibility is a precision component (between-appraiser spread) — tempting because “reproducing the right answer” sounds like accuracy.","","ndc is derived from the precision (Gage R&R) study."]},highlight:["ACCURATE"]},{id:"repeatability-vs-reproducibility",word:"REPEATABILITY vs REPRODUCIBILITY",meaning:"Repeatability = variation when the SAME person measures the SAME item repeatedly (equipment variation). Reproducibility = variation BETWEEN different people measuring the same items (appraiser variation).",whyMisread:"The words differ by a few letters and both describe “getting the same answer again”.",appears:"The measurements are inconsistent — which component is it?",actually:"Is the inconsistency within one appraiser (repeatability) or between appraisers (reproducibility)?",example:{id:"trap-repeatability-vs-reproducibility-ex",topic:"2.3.3",category:"scenario",difficulty:"trap",numerical:!1,traps:["repeatability-vs-reproducibility"],stem:"In a call-quality Gage R&R, the SAME analyst scores the same recorded call three times on different days and gives 78, 86 and 81. The averages of the three analysts are almost identical. Which component of measurement variation is the main problem?",options:["Reproducibility","Repeatability","Part-to-part variation","Bias"],answer:1,explanation:"One appraiser, one item, repeated trials, different results → repeatability (equipment/method variation). Since analysts’ averages agree, reproducibility is small.",whyWrong:["Reproducibility is the difference BETWEEN appraisers — here their averages are almost identical. This is the tempting label swap.","","Part-to-part variation is the real difference between calls; here the same call was scored, so it cannot explain the spread.","Bias is an accuracy issue versus a reference value; nothing here compares with a reference."]},tempting:0,correctInterpretation:"SAME person + SAME item + repeated = REPEATability. DIFFERENT people = REPROducibility.",strategy:"Underline who measured. One appraiser → repeatability (fix the gauge or method). Several appraisers who disagree on average → reproducibility (fix training or operational definitions).",practice:{id:"trap-repeatability-vs-reproducibility-pr",topic:"2.3.3",category:"scenario",difficulty:"trap",numerical:!1,traps:["repeatability-vs-reproducibility"],stem:"Three billing auditors each review the same 10 invoices twice. Each auditor is very consistent with themselves, but auditor C consistently records about 2 more errors per invoice than A and B. Which action BEST addresses the main measurement problem?",options:["Replace the audit software, because repeatability is poor","Align the auditors on a common operational definition of an error and retrain auditor C, because reproducibility is poor","Increase the number of invoices in the study","Accept the system, because each auditor repeats well"],answer:1,explanation:"The variation is between appraisers (C differs on average) — reproducibility. Typical fixes are clearer operational definitions, standard work and training.",whyWrong:["Each auditor is consistent with themselves, so repeatability is fine — the tempting misdiagnosis.","","More invoices does not remove a systematic appraiser difference.","Good repeatability does not compensate for poor reproducibility; both form GRR."]},highlight:["SAME analyst"]},{id:"fail-to-reject",word:"FAIL TO REJECT (never “accept”)",meaning:"When p ≥ α you “fail to reject H₀”: the data do not provide enough evidence of a difference. That is not proof that H₀ is true.",whyMisread:"Plain English suggests that if you did not reject something you must accept it. Options that say “the means are equal” sound decisive and attractive.",appears:"The test was not significant, so the groups are the same.",actually:"The test could not detect a difference with this sample; a real difference may still exist (Type II risk).",example:{id:"trap-fail-to-reject-ex",topic:"3.3.1",category:"scenario",difficulty:"trap",numerical:!0,traps:["fail-to-reject"],stem:"A Green Belt compares MTTR for two vendors with a 2-sample t-test (α = 0.05). Vendor A: n = 12, x̄ = 4.4 h, s = 1.2 h. Vendor B: n = 12, x̄ = 4.0 h, s = 1.1 h. Minitab (Welch) gives t ≈ 0.85, p ≈ 0.40. Which conclusion is correct?",options:["Accept H₀: the two vendors have the same mean MTTR","Reject H₀: vendor B is faster","Fail to reject H₀: there is not enough evidence that the mean MTTRs differ","The test is invalid because p is larger than t"],answer:2,explanation:"t = (4.4 − 4.0) ÷ √(1.2²/12 + 1.1²/12) = 0.4 ÷ 0.470 ≈ 0.85; with Welch df ≈ 21.8, two-sided p ≈ 0.40. Since p > 0.05 we fail to reject H₀. With only 12 incidents each, a real 0.4 h difference could easily go undetected.",whyWrong:["“Accept H₀ / the means are the same” claims proof of equality — the tempting wording. A hypothesis test can only fail to find evidence of a difference.","p = 0.40 is far above α = 0.05, so H₀ cannot be rejected.","","p and t are on different scales and are never compared with each other."]},tempting:0,correctInterpretation:"p ≥ α → “fail to reject H₀ — insufficient evidence of a difference”. p < α → “reject H₀ — evidence of a difference”.",strategy:"Cross out any option containing “accept H₀”, “prove” or “the means are equal”. Then ask whether the sample was large enough (power) before drawing business conclusions.",practice:{id:"trap-fail-to-reject-pr",topic:"3.3.1",category:"incorrect-statement",difficulty:"trap",numerical:!1,traps:["fail-to-reject"],stem:"A paired t-test on 8 agents before and after training gives p = 0.21 (α = 0.05). Which statement is NOT a valid interpretation?",options:["There is insufficient evidence that training changed mean handle time","The training has been proven to have no effect on handle time","A larger sample might detect a real effect if one exists","The risk of a Type II error should be considered before dropping the training"],answer:1,explanation:"Failing to reject H₀ never proves “no effect”. With only 8 pairs the test may simply lack power.",whyWrong:["This is the correct “fail to reject” wording.","","Valid — more data increases power.","Valid — a non-significant result carries β risk (missing a real effect)."]},highlight:["p ≈ 0.40"]},{id:"p-value",word:"p-VALUE",meaning:"The p-value is the probability of seeing data at least as extreme as yours IF H₀ were true. Reject H₀ when p < α — the α chosen in the question, not always 0.05.",whyMisread:"Candidates read p as “the probability that H₀ is true”, or reflexively compare it with 0.05 even when the stem sets a different α.",appears:"p = 0.03, so there is a 3% chance the null hypothesis is true.",actually:"If H₀ were true, results this extreme would occur only about 3% of the time — evidence against H₀.",example:{id:"trap-p-value-ex",topic:"3.3.2",category:"concept",difficulty:"trap",numerical:!1,traps:["p-value"],stem:"A test comparing first-contact resolution between two contact-centre sites gives p = 0.03. Which statement correctly interprets this p-value?",options:["There is a 3% probability that the null hypothesis is true","There is a 97% probability that the sites really differ","If there were truly no difference between the sites, a difference at least this large would occur by chance only about 3% of the time","The difference between the sites is 3 percentage points"],answer:2,explanation:"A p-value is calculated assuming H₀ is true; it measures how surprising the data are under H₀. It is not the probability that H₀ (or H₁) is true, and it says nothing about the size of the difference.",whyWrong:["This reverses the conditional — the most common p-value misreading and the tempting answer.","Same reversal from the other side; 1 − p is not the probability that H₁ is true.","","The p-value is a probability, not the size of the effect."]},tempting:0,correctInterpretation:"“If H₀ were true, how surprising are my data?” Small p = surprising = reject H₀.",strategy:"Find α in the stem first (it may be 0.01 or 0.10). Then apply “if p is low, the null must go”. Never read p as the probability of a hypothesis.",practice:{id:"trap-p-value-pr",topic:"3.4.1",category:"calculation",difficulty:"trap",numerical:!0,traps:["p-value"],stem:"Fibre install time target is 5.0 days. A 1-sample t-test on n = 25 installs gives x̄ = 5.6 days, s = 1.2 days. The project uses α = 0.01. What is the correct decision?",options:["Reject H₀ because p ≈ 0.020 is below 0.05","Fail to reject H₀ because p ≈ 0.020 is above α = 0.01","Reject H₀ because t = 2.5 is greater than 1","Fail to reject H₀ because p ≈ 0.98"],answer:1,explanation:"t = (5.6 − 5.0) ÷ (1.2/√25) = 0.6 ÷ 0.24 = 2.5, df = 24, two-sided p ≈ 0.020. The stated α is 0.01, and 0.020 > 0.01, so we fail to reject H₀ at this significance level.",whyWrong:["Uses the habitual 0.05 instead of the α stated in the question — the tempting slip.","","t must be compared with the critical t (≈ 2.80 for df 24 at α = 0.01 two-sided), not with 1.","0.98 is the cumulative probability below t, not the p-value."]},highlight:["p = 0.03"]},{id:"alpha-vs-beta",word:"ALPHA vs BETA (Type I vs Type II)",meaning:"α = probability of a Type I error: rejecting a TRUE H₀ (false alarm). β = probability of a Type II error: failing to reject a FALSE H₀ (missed effect). Power = 1 − β.",whyMisread:"The four combinations (truth × decision) are easy to scramble under time pressure, and “Type I/II” are abstract labels.",appears:"The team made an error — which risk is it?",actually:"Was there really no effect (but they claimed one) → α / Type I? Or was there a real effect (but they missed it) → β / Type II?",example:{id:"trap-alpha-vs-beta-ex",topic:"3.3.3",category:"scenario",difficulty:"trap",numerical:!1,traps:["alpha-vs-beta"],stem:"A team concludes from a pilot that a new triage script reduced MTTR and rolls it out. Later, a larger study shows the script made NO real difference. Which risk did the team experience?",options:["Beta risk — a Type II error","Alpha risk — a Type I error","Power — the test was too powerful","Consumer’s risk — missing a real improvement"],answer:1,explanation:"In reality H₀ (no difference) was true, but the team rejected it. Rejecting a true null is a Type I error, whose probability is α (the producer’s risk or false alarm).",whyWrong:["β is failing to detect a REAL difference — the opposite situation. This is the tempting swap.","","Power is the probability of correctly detecting a real effect; there was no real effect here.","Consumer’s risk is another name for β."]},tempting:0,correctInterpretation:"Claimed an effect that is NOT there → α (Type I, false positive). Missed an effect that IS there → β (Type II, false negative).",strategy:"Draw the 2×2 grid: columns “H₀ true / H₀ false”, rows “reject / fail to reject”. Put α in (reject, H₀ true) and β in (fail to reject, H₀ false). Place the scenario in a cell.",practice:{id:"trap-alpha-vs-beta-pr",topic:"3.3.3",category:"concept",difficulty:"trap",numerical:!1,traps:["alpha-vs-beta"],stem:"With the sample size held constant, a Green Belt lowers α from 0.05 to 0.01. What happens to β?",options:["β decreases","β increases","β stays the same","β becomes equal to α"],answer:1,explanation:"For a fixed sample size, making it harder to reject H₀ (smaller α) makes it more likely to miss a real difference, so β rises and power falls. Only a larger sample (or less noise) reduces both together.",whyWrong:["Tempting because “stricter test = fewer errors”, but it trades fewer false alarms for more missed effects.","","α and β are linked through the decision boundary; changing one moves the other when n is fixed.","There is no rule that makes them equal."]},highlight:["NO real difference"]},{id:"one-vs-two-tailed",word:"ONE-TAILED vs TWO-TAILED",meaning:"Directional wording (greater than, exceeds, reduced, less than) means a one-tailed test with all of α in one tail. Non-directional wording (different, changed) means two-tailed with α split between both tails.",whyMisread:"Software defaults to two-tailed, and candidates rarely re-read the exact question wording before choosing p.",appears:"Test the mean against 300 seconds.",actually:"Test whether the mean EXCEEDS 300 seconds — only one direction counts.",example:{id:"trap-one-vs-two-tailed-ex",topic:"3.3.4",category:"calculation",difficulty:"trap",numerical:!0,traps:["one-vs-two-tailed"],stem:"A regulator asks whether mean call-answer time EXCEEDS the 300-second limit. A random sample of n = 16 calls gives x̄ = 318 s and s = 40 s. Using α = 0.05, what is the correct p-value and decision?",options:["p ≈ 0.092 → fail to reject H₀","p ≈ 0.046 → reject H₀: the mean exceeds 300 s","p ≈ 0.954 → fail to reject H₀","p ≈ 0.023 → reject H₀"],answer:1,explanation:"H₀: μ = 300, H₁: μ > 300 (one-tailed). t = (318 − 300) ÷ (40/√16) = 18 ÷ 10 = 1.80, df = 15. Upper-tail p ≈ 0.046 < 0.05 → reject H₀. (Equivalently, t = 1.80 exceeds the one-tailed critical t of 1.753.)",whyWrong:["0.092 is the two-tailed p-value (2 × 0.046). The question is directional, so this is the tempting default-setting mistake.","","0.954 is the lower-tail probability — the wrong direction.","0.023 halves the one-tailed p-value again; there is no basis for that."]},tempting:0,correctInterpretation:"Directional words → one tail. “Different / changed / not equal” → two tails. Decide before looking at the data.",strategy:"Circle the comparison word in the stem and write H₁ with <, > or ≠ before calculating. If one-tailed and the effect is in the predicted direction, p(one) = p(two) ÷ 2.",practice:{id:"trap-one-vs-two-tailed-pr",topic:"3.3.4",category:"wording",difficulty:"trap",numerical:!1,traps:["one-vs-two-tailed"],stem:"Which question requires a TWO-tailed test?",options:["Has the new routing rule reduced average wait time?","Does network latency exceed 20 ms on average?","Is the mean billing cycle time at the new data centre different from the old one?","Is the defect rate lower than 2%?"],answer:2,explanation:"“Different from” has no direction, so H₁: μ₁ ≠ μ₂ — a two-tailed test. The other questions specify a direction.",whyWrong:["“Reduced” is directional (H₁: μ < μ₀) — one-tailed. Tempting because most tests in software default to two-tailed.","“Exceed” is directional (>) — one-tailed.","","“Lower than” is directional (<) — one-tailed."]},highlight:["EXCEEDS"]},{id:"paired-vs-independent",word:"PAIRED vs INDEPENDENT samples",meaning:"If each value in one group is linked to a specific value in the other (same item measured twice, or matched pairs), use a paired test on the differences. Otherwise the samples are independent (2-sample t, Mann-Whitney).",whyMisread:"The data are usually shown as two columns, which looks exactly like two independent groups.",appears:"Compare the two columns with a 2-sample t-test.",actually:"The rows belong to the SAME agents (or items) — analyse the differences with a paired t-test.",example:{id:"trap-paired-vs-independent-ex",topic:"3.4.1",category:"best-tool",difficulty:"trap",numerical:!0,traps:["paired-vs-independent"],stem:"The SAME 10 agents’ average handle times (s) are recorded before and after CRM training. Before: 310, 295, 330, 288, 342, 305, 318, 299, 325, 312. After: 302, 290, 318, 285, 332, 299, 309, 295, 318, 306. Which analysis is appropriate, and what does it show at α = 0.05?",options:["2-sample t-test: p ≈ 0.33, no significant change","Paired t-test: mean reduction 7.0 s, p < 0.001, significant reduction","One-way ANOVA: p ≈ 0.33, no significant change","Chi-square test of independence on the two columns"],answer:1,explanation:"Each before value pairs with an after value from the same agent. Differences: 8, 5, 12, 3, 10, 6, 9, 4, 7, 6 → mean d̄ = 7.0, s_d ≈ 2.79, t = 7.0 ÷ (2.79/√10) ≈ 7.94, df = 9, p ≈ 0.00002. A 2-sample t (Welch) would give t ≈ 1.00, p ≈ 0.33, because agent-to-agent differences (SD ≈ 15–17 s) swamp the 7-second effect.",whyWrong:["Ignoring the pairing treats agent-to-agent variation as noise and misses a clear effect — the tempting choice.","","ANOVA with two independent groups is equivalent to the 2-sample t and has the same flaw.","Chi-square tests association between categorical variables, not differences in continuous means."]},tempting:0,correctInterpretation:"Ask “does row 1 in column A belong to row 1 in column B?”. If yes → paired. If the groups contain different items → independent.",strategy:"Look for “same”, “before and after”, “each”, “matched”. For pairs, subtract first, then test the mean difference against 0.",practice:{id:"trap-paired-vs-independent-pr",topic:"3.4.1",category:"best-tool",difficulty:"trap",numerical:!1,traps:["paired-vs-independent"],stem:"A Green Belt wants to compare mean restore time of 40 incidents handled by vendor A with 35 different incidents handled by vendor B. The data are approximately normal. Which test is MOST appropriate?",options:["Paired t-test","2-sample t-test","1-sample t-test","1-sample Wilcoxon test"],answer:1,explanation:"Different incidents in each group with unequal sizes → independent samples → 2-sample t-test (Welch by default in Minitab).",whyWrong:["There is no natural pairing between vendor A and vendor B incidents (and the group sizes differ) — the tempting over-correction.","","A 1-sample test compares one mean with a target, not two groups.","A 1-sample Wilcoxon tests one median against a target."]},highlight:["SAME 10 agents"]},{id:"normality-assumption",word:"NORMALITY TEST p-value",meaning:"In a normality test H₀ is “the data are normal”. A p-value below α means REJECT normality. A large p-value means no evidence against normality.",whyMisread:"Candidates learn “small p = significant = good result” and carry it over, concluding that p = 0.003 means the data pass the normality check.",appears:"p = 0.003 is significant, so the data are normal.",actually:"p = 0.003 < 0.05 rejects normality — choose a non-parametric test, a transformation, or rely on the CLT for means of large samples.",example:{id:"trap-normality-assumption-ex",topic:"2.2.3",category:"scenario",difficulty:"trap",numerical:!1,traps:["normality-assumption"],stem:"MTTR data for three regions are strongly right-skewed. The Anderson-Darling normality test gives p = 0.003 for each region. The team wants to know whether the regions differ in typical restore time. Which approach is MOST appropriate?",options:["Run one-way ANOVA, because p = 0.003 shows the data are significantly normal","Run a Kruskal-Wallis test (or Mood’s median if there are outliers), because the data are not normal","Run three 2-sample t-tests between each pair of regions","Run a 1-sample sign test on all the data combined"],answer:1,explanation:"H₀ of the AD test is “normal”; p = 0.003 < 0.05 rejects it. For three or more independent groups of non-normal data, Kruskal-Wallis compares medians (Mood’s median is more robust to outliers). A Box-Cox transformation followed by ANOVA is another valid route.",whyWrong:["A small normality p-value means NOT normal — the reversed reading is the trap.","","Multiple t-tests inflate the overall α and still assume normality.","A 1-sample sign test compares one median with a target, not several groups."]},tempting:0,correctInterpretation:"Normality test: low p → not normal. Then pick the non-parametric equivalent: 2 groups → Mann-Whitney, 3+ groups → Kruskal-Wallis / Mood’s median, paired or 1-sample → sign or Wilcoxon.",strategy:"Write “H₀ = normal” beside any normality p-value before interpreting it. Then check the sample size: with large samples and means, the CLT may still justify t-tests or ANOVA.",practice:{id:"trap-normality-assumption-pr",topic:"3.5.1",category:"best-tool",difficulty:"trap",numerical:!1,traps:["normality-assumption"],stem:"Two contractors’ fibre repair times (n = 18 each, independent) give Anderson-Darling p-values of 0.62 and 0.01. Which test is MOST appropriate to compare their typical repair times?",options:["2-sample t-test, because one sample is normal","Mann-Whitney test","Paired t-test","One-way ANOVA"],answer:1,explanation:"One sample fails normality (p = 0.01) and the samples are small, so a parametric 2-sample t is not safe. Mann-Whitney compares medians of two independent groups without assuming normality.",whyWrong:["Both samples must be approximately normal for a small-sample t-test; one passing is not enough — the tempting shortcut.","","The groups are independent, not paired.","ANOVA with two groups is equivalent to the t-test and has the same normality requirement."]},highlight:["p = 0.003"]},{id:"correlation-causation",word:"CORRELATION is not CAUSATION",meaning:"A strong correlation shows that two variables move together. It does not show that changing one will change the other — a third variable, reverse causation or coincidence may explain it.",whyMisread:"A large r and a tiny p-value feel like proof, and the causal story often sounds plausible.",appears:"r = 0.86, so X causes Y.",actually:"There is a strong positive linear association; causation must be established by process knowledge and controlled experiments.",example:{id:"trap-correlation-causation-ex",topic:"4.1.1",category:"scenario",difficulty:"trap",numerical:!1,traps:["correlation-causation"],stem:"Across 40 regions, the number of field engineers assigned and the average MTTR have a correlation of r = 0.86 (p < 0.001). What can the team validly conclude?",options:["Assigning more engineers causes longer restore times, so engineers should be reduced","There is a strong positive linear association; another factor (such as remoteness or fault complexity) may drive both, so causation is not established","86% of the variation in MTTR is caused by the number of engineers","Because p < 0.001, the relationship must be causal"],answer:1,explanation:"Correlation measures association only. Remote, complex regions plausibly receive more engineers AND have longer restores, so a lurking variable may explain the pattern. A designed change or stratified analysis is needed before acting.",whyWrong:["Treats correlation as causation and would cut resources where they are most needed — the tempting conclusion.","","R² = 0.86² ≈ 0.74, not 0.86, and even R² describes explained variation, not caused variation.","A small p-value shows the correlation is unlikely to be zero, not that it is causal."]},tempting:0,correctInterpretation:"Read r as “how strongly do they move together in a straight line?”. Ask what else could drive both before claiming cause.",strategy:"Eliminate any option with “causes”, “proves” or “because of” when only observational correlation is given. Look for lurking variables and reverse causation.",practice:{id:"trap-correlation-causation-pr",topic:"4.1.1",category:"incorrect-statement",difficulty:"trap",numerical:!1,traps:["correlation-causation"],stem:"Which statement about the Pearson correlation coefficient r is NOT correct?",options:["r ranges from −1 to +1","r measures the strength of a linear relationship","An r close to 0 proves there is no relationship of any kind between X and Y","r = −0.9 indicates a strong negative linear relationship"],answer:2,explanation:"r only captures LINEAR association. A strong curved (e.g. U-shaped) relationship can give r ≈ 0, so always look at the scatter plot.",whyWrong:["Correct — the range of r.","Correct — r is a linear measure.","","Correct — the sign shows direction and |r| = 0.9 is strong."]},highlight:["r = 0.86"]},{id:"practical-vs-statistical",word:"STATISTICALLY vs PRACTICALLY significant",meaning:"Statistical significance says a difference is probably real. Practical significance asks whether it is big enough to matter. Very large samples make tiny differences significant; small samples can miss important ones.",whyMisread:"The word “significant” in everyday English means “important”, so p < 0.05 is read as “worth acting on”.",appears:"p < 0.05, so the improvement is important.",actually:"Compare the size of the difference with the business’s minimum worthwhile change.",example:{id:"trap-practical-vs-statistical-ex",topic:"3.3.2",category:"scenario",difficulty:"trap",numerical:!0,traps:["practical-vs-statistical"],stem:"A contact centre compares 30,000 calls before and 30,000 calls after a script tweak. Mean handle time fell from 360.0 s to 358.5 s (s = 60 s in both groups); p ≈ 0.002. Management defined a worthwhile improvement as at least 20 s. What is the BEST conclusion?",options:["The tweak is a major success because p is below 0.05","The 1.5 s reduction is statistically significant but not practically significant against the 20 s threshold","The result is neither statistically nor practically significant","The p-value is wrong because such a small difference cannot be significant"],answer:1,explanation:"SE of the difference = √(60²/30,000 + 60²/30,000) ≈ 0.49 s, so t ≈ 1.5 ÷ 0.49 ≈ 3.06 and p ≈ 0.002 — statistically significant. But the effect (1.5 s) is far below the 20 s that matters to the business.",whyWrong:["Confuses “statistically significant” with “important” — the tempting reading.","","p ≈ 0.002 < 0.05, so it IS statistically significant.","With 30,000 per group, the standard error is tiny, so very small differences become significant."]},tempting:0,correctInterpretation:"Two checks: (1) p < α? → statistically significant. (2) Is the estimated difference ≥ the minimum worthwhile change? → practically significant.",strategy:"Find the effect size in the stem and compare it with any target, cost or customer requirement. Mention both kinds of significance in your answer choice.",practice:{id:"trap-practical-vs-statistical-pr",topic:"3.3.2",category:"scenario",difficulty:"trap",numerical:!0,traps:["practical-vs-statistical"],stem:"A pilot with only 6 fibre installs per method shows the new method averaging 205 min versus 250 min (s = 40 and 50 min). The 2-sample t-test gives p ≈ 0.12. A 30-minute saving would be worth OMR 200,000 a year. What is the BEST next step?",options:["Abandon the new method — the difference is not significant","Implement immediately — the 45-minute saving is obviously real","Collect a larger sample: the observed difference is practically important but the test lacks power to confirm it statistically","Lower α to 0.01 and re-test"],answer:2,explanation:"Welch t = 45 ÷ √(40²/6 + 50²/6) ≈ 45 ÷ 26.1 ≈ 1.72, df ≈ 9.5, p ≈ 0.12 — not significant at 0.05. The 45-minute difference would be valuable, so the right move is a properly powered study, not a conclusion either way.",whyWrong:["“Not significant” with tiny samples is not evidence of no effect — the tempting over-reading of p.","The difference might be noise; p ≈ 0.12 means it is not yet confirmed.","","A smaller α makes rejection even harder and does nothing about low power."]},highlight:["p ≈ 0.002","20 s"]},{id:"defects-vs-defectives-chart",word:"DEFECTS vs DEFECTIVES (chart choice)",meaning:"Counting defective UNITS (pass/fail, binomial) → p or np chart. Counting DEFECTS where a unit can have several (Poisson) → u or c chart.",whyMisread:"Both are “attribute charts for errors”, and stems often mix the words “errors”, “defects” and “defective” loosely.",appears:"We are tracking errors — use a p chart.",actually:"Can one unit have more than one error being counted? If yes, it is defects data → u or c chart.",example:{id:"trap-defects-vs-defectives-chart-ex",topic:"5.2.4",category:"best-tool",difficulty:"trap",numerical:!1,traps:["defects-vs-defectives-chart"],stem:"A billing team audits a different number of invoices each day and records the TOTAL NUMBER OF ERRORS found; one invoice can contain several errors. Which control chart is MOST appropriate?",options:["p chart","np chart","u chart","c chart"],answer:2,explanation:"Errors are counted per invoice and an invoice can hold several, so the data are defects (Poisson). The number of invoices (area of opportunity) varies daily, so plot defects per unit on a u chart.",whyWrong:["A p chart plots the proportion of DEFECTIVE invoices; it would ignore the second and third errors on the same invoice — the tempting choice.","An np chart counts defective units with a constant sample size — wrong data type and wrong sample-size condition.","","A c chart counts defects but needs a constant area of opportunity; here the number of invoices varies."]},tempting:0,correctInterpretation:"Unit is good/bad → defectives → p (varying n) or np (constant n). Count of flaws, possibly several per unit → defects → u (varying size) or c (constant size).",strategy:"Ask two questions in order: (1) defects or defectives? (2) constant or varying sample size? Two answers pick exactly one chart.",practice:{id:"trap-defects-vs-defectives-chart-pr",topic:"5.2.6",category:"best-tool",difficulty:"trap",numerical:!1,traps:["defects-vs-defectives-chart"],stem:"Every day exactly 200 new-connection orders are checked, and each order is classified as correct or incorrect. The team wants to plot the NUMBER of incorrect orders. Which chart should they use?",options:["u chart","c chart","np chart","I-MR chart"],answer:2,explanation:"Each order is either defective or not (binomial) and n is constant at 200, so the number defective is plotted on an np chart.",whyWrong:["A u chart is for defects per unit, not pass/fail classification.","A c chart counts defects (several possible per unit) — tempting because the team is plotting a count.","","I-MR is for continuous individual measurements; it ignores the binomial nature of the data."]},highlight:["TOTAL NUMBER OF ERRORS"]},{id:"constant-vs-variable-sample",word:"CONSTANT vs VARIABLE sample size",meaning:"np and c charts require a constant sample size or area of opportunity. When sample size varies, use p or u charts, whose control limits are calculated for each subgroup’s own n.",whyMisread:"Candidates use one average sample size for all limits, or pick the np chart because counts are easier to plot.",appears:"Use the average n to set one pair of control limits.",actually:"With variable n, each point has its own limits: wider for small samples, narrower for large ones.",example:{id:"trap-constant-vs-variable-sample-ex",topic:"5.2.5",category:"calculation",difficulty:"trap",numerical:!0,traps:["constant-vs-variable-sample"],stem:"A p chart tracks the proportion of failed SIM activations. Overall p̄ = 0.05, and daily sample sizes VARY between 100 and 400 (average 250). On a day with n = 100, 10 activations failed (p = 0.10). Using the correct UCL for that day, is the point out of control?",options:["Yes — 0.10 is above the UCL of 0.091 calculated from the average n of 250","No — the UCL for n = 100 is about 0.115, so 0.10 is inside the limits","Yes — any day above p̄ is out of control","No — the UCL is always 3 × p̄ = 0.15"],answer:1,explanation:"For n = 100: UCL = p̄ + 3√[p̄(1 − p̄)/n] = 0.05 + 3√(0.05 × 0.95 ÷ 100) = 0.05 + 3 × 0.0218 ≈ 0.115. Since 0.10 < 0.115, the point is in control. Using the average n (250) gives 0.05 + 3 × 0.0138 ≈ 0.091 and a false alarm.",whyWrong:["Applies the average-n limit to a small-sample day, which makes the limit too narrow and raises a false signal — the tempting shortcut.","","Points vary around p̄ by chance; only points beyond the limits or non-random patterns are signals.","3 × p̄ is not the p-chart formula."]},tempting:0,correctInterpretation:"Variable n → p or u chart with point-by-point limits. Constant n → np or c chart (or p/u with flat limits).",strategy:"Scan the stem for “varies”, “different number each day” or “always 200”. Compute the limit using THAT subgroup’s n.",practice:{id:"trap-constant-vs-variable-sample-pr",topic:"5.2.6",category:"best-tool",difficulty:"trap",numerical:!1,traps:["constant-vs-variable-sample"],stem:"A team counts the number of defective porting requests each week. The number of requests processed ranges from 600 to 1,450 per week. Which chart is MOST appropriate?",options:["np chart","p chart","c chart","Xbar-R chart"],answer:1,explanation:"Defectives data with a varying sample size → p chart, with limits recalculated for each week’s n.",whyWrong:["The np chart assumes the same n every week — tempting because the team is counting defectives.","","The c chart is for defect counts with a constant area of opportunity.","Xbar-R is for continuous measurements in subgroups."]},highlight:["VARY"]},{id:"standard-error",word:"STANDARD ERROR vs STANDARD DEVIATION",meaning:"Standard deviation (s) describes the spread of individual values. Standard error (SE = s/√n) describes the spread of the sample MEAN and shrinks as n grows.",whyMisread:"Both are “sigma-like” numbers, and the stem usually gives s directly, so candidates use it unchanged — or divide by n instead of √n.",appears:"Use the standard deviation of the data.",actually:"Divide s by the square root of n for anything about the mean (CIs, t-statistics, X-bar limits).",example:{id:"trap-standard-error-ex",topic:"3.2.3",category:"calculation",difficulty:"trap",numerical:!0,traps:["standard-error"],stem:"Individual call handle times have a standard deviation of 60 s. A supervisor averages random samples of 36 calls. What is the standard error of the sample mean?",options:["60 s","1.67 s","10 s","3.6 s"],answer:2,explanation:"SE = s ÷ √n = 60 ÷ √36 = 60 ÷ 6 = 10 s.",whyWrong:["60 s is the standard deviation of INDIVIDUAL calls — the tempting answer, since it is given directly.","1.67 s = 60 ÷ 36 divides by n instead of √n.","","3.6 s = 36 ÷ 10 has no statistical meaning here."]},tempting:0,correctInterpretation:"About individual values → SD. About the average of n values → SE = SD ÷ √n. Quadrupling n halves SE.",strategy:"When the stem mentions averages, means, confidence intervals or X-bar charts, write “÷ √n” in your notepad immediately.",practice:{id:"trap-standard-error-pr",topic:"3.2.1",category:"calculation",difficulty:"trap",numerical:!0,traps:["standard-error"],stem:"A random sample of n = 16 fibre repairs has mean 50 min and standard deviation 12 min. Using t = 2.131 (df = 15), what is the margin of error of the 95% confidence interval for the mean repair time?",options:["± 25.6 min","± 6.4 min","± 1.6 min","± 3.0 min"],answer:1,explanation:"SE = 12 ÷ √16 = 3 min. Margin = t × SE = 2.131 × 3 ≈ 6.39 min, so the 95% CI is about 43.6 to 56.4 min.",whyWrong:["25.6 = 2.131 × 12 uses the standard deviation instead of the standard error — the tempting slip.","","1.6 = 2.131 × 12 ÷ 16 divides by n rather than √n.","3.0 is the standard error alone, without the t multiplier."]},highlight:["standard error"]},{id:"r-squared",word:"R² vs r (and adjusted R²)",meaning:"r (−1 to +1) measures direction and strength of a linear relationship. R² (0–100%) is the share of variation in Y explained by the model; in simple regression R² = r². Adjusted R² penalises extra predictors.",whyMisread:"Candidates quote r as a percentage of variation explained, keep the minus sign, or believe a rising R² always means a better model.",appears:"r = −0.7, so the model explains 70% of the variation.",actually:"R² = (−0.7)² = 0.49 → 49% of the variation is explained.",example:{id:"trap-r-squared-ex",topic:"4.1.2",category:"calculation",difficulty:"trap",numerical:!0,traps:["r-squared"],stem:"In a simple linear regression of first-contact resolution % on agent tenure, the correlation coefficient is r = −0.70. What percentage of the variation in first-contact resolution is explained by the model (R²)?",options:["70%","−49%","49%","30%"],answer:2,explanation:"In simple linear regression R² = r² = (−0.70)² = 0.49, i.e. 49% of the variation is explained. R² cannot be negative.",whyWrong:["70% quotes |r| as if it were R² — the tempting slip.","Squaring removes the sign; R² is always between 0 and 1.","","30% = 1 − 0.70 has no meaning here (1 − R² = 51% is the unexplained share)."]},tempting:0,correctInterpretation:"Square r to get R². Read R² as “% of the variation in Y explained”. Use adjusted R² to compare models with different numbers of X’s.",strategy:"If the stem gives r but asks about “variation explained”, square it. If it compares models, look at adjusted R² — and remember R² never falls when you add a term.",practice:{id:"trap-r-squared-pr",topic:"4.2.2",category:"scenario",difficulty:"trap",numerical:!1,traps:["r-squared"],stem:"Adding “day of week” to a multiple regression of MTTR raises R² from 71.0% to 72.0%, while adjusted R² falls from 69.0% to 67.5% and the new term has p = 0.48. What should the analyst conclude?",options:["Keep the term, because R² increased","Remove the term: it adds no real explanatory power, as shown by the falling adjusted R² and its high p-value","The model is now overfitted to 72%, so remove all terms","Adjusted R² must be wrong because it cannot fall when R² rises"],answer:1,explanation:"R² always rises (or stays the same) when any term is added, even a useless one. Adjusted R² penalises the extra term and fell, and the term is not significant (p = 0.48), so it should be removed.",whyWrong:["Relying on raw R² is the classic trap — it can never go down when predictors are added.","","Only the non-significant term should be removed, not the whole model.","Adjusted R² can and often does fall when a weak term is added — that is its purpose."]},highlight:["r = −0.70"]}];Object.fromEntries(c.map(e=>[e.id,e]));const l={rpn:"2.1.4",mean:"2.2.2",stdev:"2.2.2",zscore:"2.2.3",cp:"2.4.1",cpk:"2.4.1",ppk:"2.4.1",grr:"2.3.3",sigmaLevel:"2.4.3",stderr:"3.2.3",ci:"3.2.1",sampleSize:"3.2.2",ttest1:"3.4.1",ttest2:"3.4.1",pairedT:"3.4.1",anova:"3.4.3",chisq:"3.5.8",prop1:"3.5.7",correlation:"4.1.1",regression:"4.1.2",rsq:"4.1.2",xbarR:"5.2.3",imr:"5.2.2",pchart:"5.2.5",npchart:"5.2.6",uchart:"5.2.4",cbr:"5.3.1"};function m(e){var a;const t=(a=i[e])==null?void 0:a.syllabusRef;return t&&n[t]?t:r[e]??l[e]??"1.2.5"}function f(e){var t;return((t=i[e])==null?void 0:t.name)??s[e]??o(e)}export{c as T,m as a,f};
